drop policy if exists scene_tokens_member_select on public.scene_tokens;
create policy scene_tokens_member_select on public.scene_tokens for select to authenticated using ((exists (select 1 from public.scenes s join public.campaign_members m on m.campaign_id = s.campaign_id where s.id = scene_tokens.scene_id and m.user_id = auth.uid()) or exists (select 1 from public.scenes s join public.campaigns c on c.id = s.campaign_id where s.id = scene_tokens.scene_id and c.owner_id = auth.uid())) and (not is_hidden or owner_id = auth.uid() or exists (select 1 from public.scenes s join public.campaigns c on c.id = s.campaign_id where s.id = scene_tokens.scene_id and c.owner_id = auth.uid()) or exists (select 1 from public.scenes s join public.campaign_members m on m.campaign_id = s.campaign_id where s.id = scene_tokens.scene_id and m.user_id = auth.uid() and m.role = 'gm')));
drop policy if exists scene_tokens_owner_write on public.scene_tokens;
create policy scene_tokens_owner_write on public.scene_tokens for all to authenticated using (owner_id = auth.uid() or exists (select 1 from public.scenes s join public.campaigns c on c.id = s.campaign_id where s.id = scene_tokens.scene_id and c.owner_id = auth.uid()) or exists (select 1 from public.scenes s join public.campaign_members m on m.campaign_id = s.campaign_id where s.id = scene_tokens.scene_id and m.user_id = auth.uid() and m.role = 'gm')) with check (owner_id = auth.uid() or exists (select 1 from public.scenes s join public.campaigns c on c.id = s.campaign_id where s.id = scene_tokens.scene_id and c.owner_id = auth.uid()) or exists (select 1 from public.scenes s join public.campaign_members m on m.campaign_id = s.campaign_id where s.id = scene_tokens.scene_id and m.user_id = auth.uid() and m.role = 'gm'));
